select id, seller_id, buyer_id, address_id, order_no, remark, amount, discount, status, pay_method, create_time, update_time
from `order`


        and seller_id = #{sellerId}


        and buyer_id = #{buyerId}


        and address_id = #{addressId}


        and order_no like concat('%', #{orderNo}, '%')


        and status = #{status}


        and pay_method = #{payMethod}


        and amount = #{amount}


order by create_time desc

